def fibonacci(n):
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        a, b = 0, 1
        for _ in range(2, n + 1):
            a, b = b, a + b
        return b

fib_20 = fibonacci(20)
print(f'{fib_20=}')

def nearest_palindrome(n):
    s = str(n)
    l = len(s)
    mid = (l + 1) // 2
    left = s[:mid]

    if l % 2 == 0:
        palindrome1 = left + left[::-1]
    else:
        palindrome1 = left + left[:-1][::-1]
    palindrome1 = int(palindrome1)

    if palindrome1 <= n:
        left_num = int(left)
        new_left = str(left_num + 1)
        if len(new_left) > mid:  # Handle overflow
            new_left = '1' + '0' * (mid - 1)

        if l % 2 == 0:
            palindrome2 = new_left + new_left[::-1]
        else:
            palindrome2 = new_left + new_left[:-1][::-1]

        palindrome2 = int(palindrome2)

        if abs(n - palindrome1) <= abs(n - palindrome2):
            return palindrome1
        else:
            return palindrome2
    else:
        left_num = int(left)
        new_left = str(left_num - 1)
        if len(new_left) < mid and len(new_left) > 0:  # Handle underflow
            new_left = '9' * (mid - 1)
        elif len(new_left) == 0:
            new_left = '0'
            return 0


        if l % 2 == 0:
            palindrome2 = new_left + new_left[::-1]
        else:
            palindrome2 = new_left + new_left[:-1][::-1]

        palindrome2 = int(palindrome2)

        if abs(n - palindrome1) <= abs(n - palindrome2):
            return palindrome1
        else:
            return palindrome2

nearest_pal = nearest_palindrome(fib_20)
print(f'{nearest_pal=}')
